// ── Une ligne par zone à situer sur la carte ─────────────────────────────────
const c = $('Config').first().json;
const liste = (s) => String(s ?? '').split(/[;\n]/).map((x) => x.trim()).filter(Boolean);
const zones = liste(c.zones);
if (!zones.length || !liste(c.activites).length) {
  throw new Error('Remplis au moins une activité et une zone dans Config (séparées par des « ; »).');
}
return zones.map((zone) => ({ json: { zone, recherche: `${zone}, ${c.pays}` } }));

// ─────────────────────────────────────────────────────────────────────────────
// Fonctions communes aux 5 templates « Lead Connector ».
// Le builder colle ce fichier EN TÊTE de chaque node Code qui en a besoin :
// n8n n'a pas d'import entre nodes, chaque node doit être autonome.
// ─────────────────────────────────────────────────────────────────────────────

// Lit a[i][j][k]… sans planter si une case manque (le JSON de Google Maps est un
// tableau de tableaux sans noms de champs : une case absente = null).
const lire = (a, ...chemin) => {
  for (const k of chemin) {
    if (a === null || a === undefined) return null;
    a = a[k];
  }
  return a === undefined ? null : a;
};

const nettoyer = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// Décode les entités HTML les plus courantes (Brave, sites web).
const decoderHtml = (s) => nettoyer(String(s ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&#x27;|&#39;|&apos;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16))));

// Les réseaux sociaux et agrégateurs ne comptent pas comme un « vrai » site web.
const RESEAUX = /(facebook\.com|fb\.com|instagram\.com|tiktok\.com|linktr\.ee|wa\.me|whatsapp\.com|twitter\.com|x\.com|linkedin\.com|youtube\.com|beacons\.ai|taplink|business\.site|sites\.google\.com)/i;

const estUnVraiSite = (url) => !!url && !RESEAUX.test(url);

// Nom de domaine sans « www. » (sans `new URL()`, absent du bac à sable n8n).
const domaine = (url) => ((String(url ?? '').match(/^https?:\/\/([^/?#:]+)/i) || [])[1] || '').replace(/^www\./i, '').toLowerCase();

// Garde seulement les chiffres d'un numéro au format international.
// « +237 6 71 03 33 33 » → « 237671033333 »
const chiffres = (tel) => String(tel ?? '').replace(/\D/g, '');

// Cameroun : les mobiles commencent par 6 (WhatsApp), les fixes par 2.
// Pour les autres pays on ne sait pas : on suppose que c'est un mobile.
const estMobile = (internat) => {
  if (internat.startsWith('237')) return internat.charAt(3) === '6';
  return internat.length >= 10;
};

// Remplace {nom}, {ville}, … dans un modèle de message.
const remplir = (modele, valeurs) =>
  String(modele ?? '').replace(/\{(\w+)\}/g, (m, cle) => (valeurs[cle] ?? '') === '' ? m : String(valeurs[cle]));

const lienWhatsApp = (internat, message) =>
  internat ? `https://wa.me/${internat}${message ? '?text=' + encodeURIComponent(message) : ''}` : '';

// « PHARMACIE OLEZOA, Yaoundé » → « PHARMACIE OLEZOA » (pour un message qui sonne humain).
// On enlève le dernier morceau après une virgule ou un tiret s'il contient la ville.
const sansAccents = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const nomCourt = (nom, ...villes) => {
  const n = nettoyer(nom);
  const vs = villes.filter(Boolean).map((v) => sansAccents(String(v).split(',')[0].trim())).filter(Boolean);
  const m = n.match(/^(.*\S)\s*[,|–-]\s*([^,|–-]+)$/);
  if (m && vs.some((v) => sansAccents(m[2]).includes(v))) return m[1].trim();
  return n;
};

const aujourdhui = () => new Date().toISOString().slice(0, 10);

// Emails : on enlève les faux positifs classiques (images, exemples, trackers).
const extraireEmails = (texte) => [...new Set(
  (String(texte ?? '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
    .map((e) => e.toLowerCase().replace(/^(?:u003e|x3e|mailto:)/, ''))
    .filter((e) => !/\.(png|jpe?g|gif|webp|svg|css|js)$/.test(e))
    .filter((e) => !/(example\.|domain\.com|sentry|wixpress|yourname|votre|email\.com$|@2x|godaddy)/.test(e))
)];

// Téléphones écrits dans un texte libre (extrait Facebook, page contact…).
// Format international : gardé seulement s'il commence par l'indicatif du pays visé
// (sinon on attrape des numéros de commande, des identifiants…). Pour le Cameroun,
// on reconnaît aussi les numéros locaux à 9 chiffres qui commencent par 6 ou 2.
const extraireTelephones = (texte, indicatif = '237') => {
  const t = String(texte ?? '');
  const trouves = new Set();
  for (const m of t.match(/\+\d[\d\s.\-()]{7,16}\d/g) || []) {
    const c = chiffres(m);
    if (c.length >= 10 && c.length <= 15 && (!indicatif || c.startsWith(indicatif))) trouves.add(c);
  }
  if (indicatif === '237') {
    for (const m of t.match(/(?<![\d+])(?:237[\s.]?)?[62](?:[\s.\-]?\d){8}(?!\d)/g) || []) {
      let c = chiffres(m);
      if (c.length === 9) c = '237' + c;
      if (c.length === 12) trouves.add(c);
    }
  }
  return [...trouves];
};

// Range les emails : ceux du domaine du site d'abord, puis gmail/yahoo…, puis les autres
// (souvent l'agence qui a fait le site, en bas de page).
const classerEmails = (emails, domaineSite) => {
  const gratuit = /@(gmail|yahoo|hotmail|outlook|live|icloud|aol|ymail)\./i;
  const rang = (e) => (domaineSite && e.endsWith('@' + domaineSite) || (domaineSite && e.split('@')[1]?.endsWith('.' + domaineSite)) ? 0 : gratuit.test(e) ? 1 : 2);
  return [...emails].sort((a, b) => rang(a) - rang(b));
};

const formaterTel = (internat) => (internat ? '+' + internat : '');

// « 7,688 followers » / « 5 197 J'aime » / « 1,2 K abonnés » → nombre
const lireNombre = (s) => {
  if (!s) return null;
  let t = String(s).replace(/\s/g, '').replace(/,(?=\d{3}\b)/g, '').replace(',', '.');
  const k = /k$/i.test(t) ? 1000 : /m$/i.test(t) ? 1000000 : 1;
  const n = parseFloat(t);
  return Number.isFinite(n) ? Math.round(n * k) : null;
};

// Priorité lisible à partir du score.
const priorite = (score) => (score >= 60 ? 'Chaud' : score >= 35 ? 'Tiède' : 'Froid');

// ─────────────────────────────────────────────────────────────────────────────
// Format commun d'un lead, quelle que soit la source, et fusion des doublons.
// Deux leads sont la même entreprise s'ils partagent : le même téléphone, le même site,
// la même page Facebook, le même email, la même fiche Google, ou le même nom dans la même zone.
// ─────────────────────────────────────────────────────────────────────────────

const nouveauLead = (champs) => ({
  nom: '', activite: '', zone: '', sources: [], telephones: [], emails: [],
  siteWeb: '', facebook: '', fbCle: '', instagram: '', adresse: '', categorie: '',
  placeId: '', lienMaps: '', note: null, avis: null, revendique: null, horaires: null,
  abonnes: null, latitude: null, longitude: null, extrait: '',
  ...champs,
});

const clesDuLead = (l) => {
  const cles = [];
  if (l.placeId) cles.push('p:' + l.placeId);
  for (const t of l.telephones) if (t.length >= 11) cles.push('t:' + t);
  if (estUnVraiSite(l.siteWeb)) cles.push('d:' + domaine(l.siteWeb));
  if (l.fbCle) cles.push('f:' + l.fbCle);
  for (const e of l.emails) cles.push('e:' + e);
  const n = sansAccents(nomCourt(l.nom, l.zone)).replace(/[^a-z0-9]/g, '');
  if (n.length >= 4) cles.push('n:' + n + '|' + sansAccents(l.zone));
  return cles;
};

// Union-find : chaque groupe de leads qui partagent une clé devient UNE entreprise.
const fusionner = (leads) => {
  const parent = leads.map((_, i) => i);
  const racine = (i) => (parent[i] === i ? i : (parent[i] = racine(parent[i])));
  const vu = new Map();
  leads.forEach((l, i) => {
    for (const k of clesDuLead(l)) {
      if (vu.has(k)) parent[racine(i)] = racine(vu.get(k)); else vu.set(k, i);
    }
  });
  const groupes = new Map();
  leads.forEach((l, i) => { const r = racine(i); if (!groupes.has(r)) groupes.set(r, []); groupes.get(r).push(l); });

  const ORDRE_NOM = ['Google Maps', 'OpenStreetMap', 'Facebook', 'Web'];
  return [...groupes.values()].map((g) => {
    g.sort((a, b) => ORDRE_NOM.indexOf(a.sources[0]) - ORDRE_NOM.indexOf(b.sources[0]));
    const m = nouveauLead({ ...g[0] });
    m.sources = [...new Set(g.flatMap((l) => l.sources))];
    m.telephones = [...new Set(g.flatMap((l) => l.telephones))];
    m.emails = [...new Set(g.flatMap((l) => l.emails))];
    m.siteWeb = (g.find((l) => estUnVraiSite(l.siteWeb)) || g.find((l) => l.siteWeb) || {}).siteWeb || '';
    for (const champ of ['facebook', 'fbCle', 'instagram', 'adresse', 'categorie', 'placeId', 'lienMaps', 'extrait']) {
      m[champ] = (g.find((l) => l[champ]) || {})[champ] || '';
    }
    for (const champ of ['note', 'avis', 'revendique', 'horaires', 'abonnes', 'latitude', 'longitude']) {
      const x = g.find((l) => l[champ] !== null && l[champ] !== undefined && l[champ] !== '');
      m[champ] = x ? x[champ] : null;
    }
    m.id = m.placeId ? 'p:' + m.placeId : m.fbCle ? 'f:' + m.fbCle : estUnVraiSite(m.siteWeb) ? 'd:' + domaine(m.siteWeb)
      : m.telephones[0] ? 't:' + m.telephones[0] : 'n:' + sansAccents(m.nom).replace(/[^a-z0-9]/g, '') + '|' + sansAccents(m.zone);
    return m;
  });
};

// Correspondance activité (en français) → étiquettes OpenStreetMap. Complète la liste si besoin.
const TAGS_OSM = {
  pharmacie: ['amenity=pharmacy'], restaurant: ['amenity=restaurant', 'amenity=fast_food'],
  'salon de coiffure': ['shop=hairdresser', 'shop=beauty'], coiffure: ['shop=hairdresser'], beaute: ['shop=beauty', 'shop=cosmetics'],
  boulangerie: ['shop=bakery'], patisserie: ['shop=pastry', 'shop=bakery'], hotel: ['tourism=hotel', 'tourism=guest_house'],
  supermarche: ['shop=supermarket'], quincaillerie: ['shop=hardware', 'shop=doityourself'], clinique: ['amenity=clinic', 'amenity=hospital'],
  ecole: ['amenity=school'], garage: ['shop=car_repair'], bar: ['amenity=bar', 'amenity=pub'], cafe: ['amenity=cafe'],
  boutique: ['shop=clothes', 'shop=boutique'], vetements: ['shop=clothes'], librairie: ['shop=books', 'shop=stationery'],
  telephone: ['shop=mobile_phone'], banque: ['amenity=bank'], 'agence immobiliere': ['office=estate_agent'],
};
const requeteOsm = (activite, bbox) => {
  const a = sansAccents(activite);
  const tags = Object.entries(TAGS_OSM).filter(([k]) => a.includes(k)).flatMap(([, v]) => v);
  const zone = bbox.join(',');
  const mot = activite.replace(/["\\]/g, '');
  const lignes = [...new Set(tags)].map((t) => { const [k, v] = t.split('='); return `nwr["${k}"="${v}"](${zone});`; });
  lignes.push(`nwr["name"~"${mot}",i](${zone});`);
  return `[out:json][timeout:60];(${lignes.join('')});out center tags 400;`;
};

// ── Une tâche par source × activité × zone (seulement pour les sources activées) ─
const c = $('Config').first().json;
const oui = (v) => v === true || v === 'true';
const liste = (s) => String(s ?? '').split(/[;\n]/).map((x) => x.trim()).filter(Boolean);
const nb = Math.min(Number(c.resultatsParRecherche) || 40, 100);
const taches = [];
$input.all().forEach((item, i) => {
  const zone = $('Liste des zones').itemMatching(i).json.zone;
  let geo = null;
  try { geo = JSON.parse(item.json.data || '[]')[0] || null; } catch (e) { geo = null; }
  const lat = geo ? Number(geo.lat) : null, lng = geo ? Number(geo.lon) : null;
  const [s, n, w, e] = geo ? (geo.boundingbox || []).map(Number) : [];
  const rayon = geo && Number.isFinite(s) ? Math.round(Math.min(60000, Math.max(3000, (n - s) * 111000))) : 30000;
  for (const activite of liste(c.activites)) {
    const base = { activite, zone };
    if (oui(c.sourceGoogleMaps)) taches.push({ ...base, source: 'maps',
      q: geo ? activite : `${activite} ${zone} ${c.pays}`,
      pb: geo ? `!4m8!1m3!1d${rayon}!2d${lng}!3d${lat}!3m2!1i1024!2i768!4f13.1!7i${nb}!8i0!10b1`
              : `!4m8!1m3!1d3000000!2d0!3d0!3m2!1i1024!2i768!4f13.1!7i${nb}!8i0!10b1` });
    if (oui(c.sourceFacebook)) taches.push({ ...base, source: 'facebook',
      corpsSerper: { q: `site:facebook.com ${activite} ${zone}`, gl: c.codePays, hl: c.langue } });
    if (oui(c.sourceWeb)) taches.push({ ...base, source: 'web',
      corpsSerper: { q: `${activite} ${zone}`, gl: c.codePays, hl: c.langue } });
    if (oui(c.sourceOpenStreetMap) && geo && Number.isFinite(s)) taches.push({ ...base, source: 'osm',
      requeteOsm: requeteOsm(activite, [s, w, n, e]) });
  }
});
if (!taches.length) throw new Error('Aucune source activée, ou aucune activité/zone dans Config.');
return taches.map((json) => ({ json }));

