// ─────────────────────────────────────────────────────────────────────────────
// Lecture de la réponse « tbm=map » de Google Maps (sans clé API).
//
// C'est la requête que la page Google Maps envoie elle-même quand on tape une
// recherche. La réponse commence par  )]}'  puis un gros tableau JSON sans noms
// de champs. Positions repérées le 2026-10-11 (si Google les change, c'est ici
// qu'on corrige) :
//   [11] nom            [39] adresse          [14] quartier     [166] ville
//   [13] catégories     [7][0] site web       [178][0][1][1][0] téléphone intl
//   [4][7] note         [4][8] nombre d'avis (parfois absent)  [9][2],[9][3] lat, lng
//   [78] place_id       [49] lien « Revendiquer cet établissement » (présent =
//   profil NON revendiqué par le propriétaire)   [203] horaires
// ─────────────────────────────────────────────────────────────────────────────

const lireReponseMaps = (texte) => {
  let t = typeof texte === 'string' ? texte : JSON.stringify(texte ?? '');
  if (t.startsWith(")]}'")) t = t.slice(t.indexOf('\n') + 1);
  let brut;
  try { brut = JSON.parse(t); } catch (e) { return { recherche: '', lieux: [], erreur: 'réponse illisible' }; }
  const recherche = lire(brut, 0, 0) || '';
  const lieux = [];
  for (const r of lire(brut, 0, 1) || []) {
    const p = Array.isArray(r) ? r[14] : null;
    if (!p) continue;
    let site = lire(p, 7, 0) || '';
    if (site.startsWith('/url?q=')) {
      try { site = decodeURIComponent(site.slice(7).split('&')[0]); } catch (e) { /* on garde tel quel */ }
    }
    const telIntl = lire(p, 178, 0, 1, 1, 0) || '';
    const placeId = lire(p, 78) || lire(p, 10) || '';
    const nom = nettoyer(lire(p, 11));
    lieux.push({
      nom,
      categorie: (lire(p, 13) || []).join(', '),
      adresse: nettoyer(lire(p, 39) || lire(p, 18)),
      quartier: nettoyer(lire(p, 14)),
      ville: nettoyer(lire(p, 166)),
      telephone: telIntl,
      telephoneChiffres: chiffres(telIntl),
      siteWeb: site,
      note: lire(p, 4, 7),
      // Google n'envoie pas toujours le nombre d'avis (constaté le 2026-10-11 : présent dans
      // une réponse, absent de la suivante pour la même recherche). null = « on ne sait pas ».
      avis: lire(p, 4, 8),
      revendique: !lire(p, 49),
      horaires: !!lire(p, 203, 0),
      latitude: lire(p, 9, 2),
      longitude: lire(p, 9, 3),
      placeId,
      lienMaps: placeId.startsWith('ChI')
        ? `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(nom)}&query_place_id=${placeId}`
        : `https://www.google.com/maps/search/${encodeURIComponent(nom + ' ' + (lire(p, 39) || ''))}`,
    });
  }
  return { recherche, lieux, erreur: lieux.length ? '' : 'aucun résultat' };
};

// ─────────────────────────────────────────────────────────────────────────────
// Format commun d'un lead, quelle que soit la source, et fusion des doublons.
// Deux leads sont la même entreprise s'ils partagent : le même téléphone, le même site,
// la même page Facebook, le même email, la même fiche Google, ou le même nom dans la même zone.
// ─────────────────────────────────────────────────────────────────────────────

const nouveauLead = (champs) => ({
  nom: '', activite: '', zone: '', sources: [], telephones: [], emails: [],
  siteWeb: '', facebook: '', fbCle: '', instagram: '', adresse: '', categorie: '',
  placeId: '', lienMaps: '', note: null, avis: null, revendique: null, horaires: null,
  abonnes: null, latitude: null, longitude: null, extrait: '',
  ...champs,
});

const clesDuLead = (l) => {
  const cles = [];
  if (l.placeId) cles.push('p:' + l.placeId);
  for (const t of l.telephones) if (t.length >= 11) cles.push('t:' + t);
  if (estUnVraiSite(l.siteWeb)) cles.push('d:' + domaine(l.siteWeb));
  if (l.fbCle) cles.push('f:' + l.fbCle);
  for (const e of l.emails) cles.push('e:' + e);
  const n = sansAccents(nomCourt(l.nom, l.zone)).replace(/[^a-z0-9]/g, '');
  if (n.length >= 4) cles.push('n:' + n + '|' + sansAccents(l.zone));
  return cles;
};

// Union-find : chaque groupe de leads qui partagent une clé devient UNE entreprise.
const fusionner = (leads) => {
  const parent = leads.map((_, i) => i);
  const racine = (i) => (parent[i] === i ? i : (parent[i] = racine(parent[i])));
  const vu = new Map();
  leads.forEach((l, i) => {
    for (const k of clesDuLead(l)) {
      if (vu.has(k)) parent[racine(i)] = racine(vu.get(k)); else vu.set(k, i);
    }
  });
  const groupes = new Map();
  leads.forEach((l, i) => { const r = racine(i); if (!groupes.has(r)) groupes.set(r, []); groupes.get(r).push(l); });

  const ORDRE_NOM = ['Google Maps', 'OpenStreetMap', 'Facebook', 'Web'];
  return [...groupes.values()].map((g) => {
    g.sort((a, b) => ORDRE_NOM.indexOf(a.sources[0]) - ORDRE_NOM.indexOf(b.sources[0]));
    const m = nouveauLead({ ...g[0] });
    m.sources = [...new Set(g.flatMap((l) => l.sources))];
    m.telephones = [...new Set(g.flatMap((l) => l.telephones))];
    m.emails = [...new Set(g.flatMap((l) => l.emails))];
    m.siteWeb = (g.find((l) => estUnVraiSite(l.siteWeb)) || g.find((l) => l.siteWeb) || {}).siteWeb || '';
    for (const champ of ['facebook', 'fbCle', 'instagram', 'adresse', 'categorie', 'placeId', 'lienMaps', 'extrait']) {
      m[champ] = (g.find((l) => l[champ]) || {})[champ] || '';
    }
    for (const champ of ['note', 'avis', 'revendique', 'horaires', 'abonnes', 'latitude', 'longitude']) {
      const x = g.find((l) => l[champ] !== null && l[champ] !== undefined && l[champ] !== '');
      m[champ] = x ? x[champ] : null;
    }
    m.id = m.placeId ? 'p:' + m.placeId : m.fbCle ? 'f:' + m.fbCle : estUnVraiSite(m.siteWeb) ? 'd:' + domaine(m.siteWeb)
      : m.telephones[0] ? 't:' + m.telephones[0] : 'n:' + sansAccents(m.nom).replace(/[^a-z0-9]/g, '') + '|' + sansAccents(m.zone);
    return m;
  });
};

// Correspondance activité (en français) → étiquettes OpenStreetMap. Complète la liste si besoin.
const TAGS_OSM = {
  pharmacie: ['amenity=pharmacy'], restaurant: ['amenity=restaurant', 'amenity=fast_food'],
  'salon de coiffure': ['shop=hairdresser', 'shop=beauty'], coiffure: ['shop=hairdresser'], beaute: ['shop=beauty', 'shop=cosmetics'],
  boulangerie: ['shop=bakery'], patisserie: ['shop=pastry', 'shop=bakery'], hotel: ['tourism=hotel', 'tourism=guest_house'],
  supermarche: ['shop=supermarket'], quincaillerie: ['shop=hardware', 'shop=doityourself'], clinique: ['amenity=clinic', 'amenity=hospital'],
  ecole: ['amenity=school'], garage: ['shop=car_repair'], bar: ['amenity=bar', 'amenity=pub'], cafe: ['amenity=cafe'],
  boutique: ['shop=clothes', 'shop=boutique'], vetements: ['shop=clothes'], librairie: ['shop=books', 'shop=stationery'],
  telephone: ['shop=mobile_phone'], banque: ['amenity=bank'], 'agence immobiliere': ['office=estate_agent'],
};
const requeteOsm = (activite, bbox) => {
  const a = sansAccents(activite);
  const tags = Object.entries(TAGS_OSM).filter(([k]) => a.includes(k)).flatMap(([, v]) => v);
  const zone = bbox.join(',');
