// ─────────────────────────────────────────────────────────────────────────────
// Fonctions communes aux 5 templates « Lead Connector ».
// Le builder colle ce fichier EN TÊTE de chaque node Code qui en a besoin :
// n8n n'a pas d'import entre nodes, chaque node doit être autonome.
// ─────────────────────────────────────────────────────────────────────────────

// Lit a[i][j][k]… sans planter si une case manque (le JSON de Google Maps est un
// tableau de tableaux sans noms de champs : une case absente = null).
const lire = (a, ...chemin) => {
  for (const k of chemin) {
    if (a === null || a === undefined) return null;
    a = a[k];
  }
  return a === undefined ? null : a;
};

const nettoyer = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();

// Décode les entités HTML les plus courantes (Brave, sites web).
const decoderHtml = (s) => nettoyer(String(s ?? '')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&#x27;|&#39;|&apos;/g, "'")
  .replace(/&quot;/g, '"')
  .replace(/&amp;/g, '&')
  .replace(/&lt;/g, '<')
  .replace(/&gt;/g, '>')
  .replace(/&nbsp;/g, ' ')
  .replace(/&#(\d+);/g, (_, n) => String.fromCharCode(Number(n)))
  .replace(/&#x([0-9a-f]+);/gi, (_, n) => String.fromCharCode(parseInt(n, 16))));

// Les réseaux sociaux et agrégateurs ne comptent pas comme un « vrai » site web.
const RESEAUX = /(facebook\.com|fb\.com|instagram\.com|tiktok\.com|linktr\.ee|wa\.me|whatsapp\.com|twitter\.com|x\.com|linkedin\.com|youtube\.com|beacons\.ai|taplink|business\.site|sites\.google\.com)/i;

const estUnVraiSite = (url) => !!url && !RESEAUX.test(url);

// Nom de domaine sans « www. » (sans `new URL()`, absent du bac à sable n8n).
const domaine = (url) => ((String(url ?? '').match(/^https?:\/\/([^/?#:]+)/i) || [])[1] || '').replace(/^www\./i, '').toLowerCase();

// Garde seulement les chiffres d'un numéro au format international.
// « +237 6 71 03 33 33 » → « 237671033333 »
const chiffres = (tel) => String(tel ?? '').replace(/\D/g, '');

// Cameroun : les mobiles commencent par 6 (WhatsApp), les fixes par 2.
// Pour les autres pays on ne sait pas : on suppose que c'est un mobile.
const estMobile = (internat) => {
  if (internat.startsWith('237')) return internat.charAt(3) === '6';
  return internat.length >= 10;
};

// Remplace {nom}, {ville}, … dans un modèle de message.
const remplir = (modele, valeurs) =>
  String(modele ?? '').replace(/\{(\w+)\}/g, (m, cle) => (valeurs[cle] ?? '') === '' ? m : String(valeurs[cle]));

const lienWhatsApp = (internat, message) =>
  internat ? `https://wa.me/${internat}${message ? '?text=' + encodeURIComponent(message) : ''}` : '';

// « PHARMACIE OLEZOA, Yaoundé » → « PHARMACIE OLEZOA » (pour un message qui sonne humain).
// On enlève le dernier morceau après une virgule ou un tiret s'il contient la ville.
const sansAccents = (s) => String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const nomCourt = (nom, ...villes) => {
  const n = nettoyer(nom);
  const vs = villes.filter(Boolean).map((v) => sansAccents(String(v).split(',')[0].trim())).filter(Boolean);
  const m = n.match(/^(.*\S)\s*[,|–-]\s*([^,|–-]+)$/);
  if (m && vs.some((v) => sansAccents(m[2]).includes(v))) return m[1].trim();
  return n;
};

const aujourdhui = () => new Date().toISOString().slice(0, 10);

// Emails : on enlève les faux positifs classiques (images, exemples, trackers).
const extraireEmails = (texte) => [...new Set(
  (String(texte ?? '').match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
    .map((e) => e.toLowerCase().replace(/^(?:u003e|x3e|mailto:)/, ''))
    .filter((e) => !/\.(png|jpe?g|gif|webp|svg|css|js)$/.test(e))
    .filter((e) => !/(example\.|domain\.com|sentry|wixpress|yourname|votre|email\.com$|@2x|godaddy)/.test(e))
)];

// Téléphones écrits dans un texte libre (extrait Facebook, page contact…).
// Format international : gardé seulement s'il commence par l'indicatif du pays visé
// (sinon on attrape des numéros de commande, des identifiants…). Pour le Cameroun,
// on reconnaît aussi les numéros locaux à 9 chiffres qui commencent par 6 ou 2.
const extraireTelephones = (texte, indicatif = '237') => {
  const t = String(texte ?? '');
  const trouves = new Set();
  for (const m of t.match(/\+\d[\d\s.\-()]{7,16}\d/g) || []) {
    const c = chiffres(m);
    if (c.length >= 10 && c.length <= 15 && (!indicatif || c.startsWith(indicatif))) trouves.add(c);
  }
  if (indicatif === '237') {
    for (const m of t.match(/(?<![\d+])(?:237[\s.]?)?[62](?:[\s.\-]?\d){8}(?!\d)/g) || []) {
      let c = chiffres(m);
      if (c.length === 9) c = '237' + c;
      if (c.length === 12) trouves.add(c);
    }
  }
  return [...trouves];
};

// Range les emails : ceux du domaine du site d'abord, puis gmail/yahoo…, puis les autres
// (souvent l'agence qui a fait le site, en bas de page).
const classerEmails = (emails, domaineSite) => {
  const gratuit = /@(gmail|yahoo|hotmail|outlook|live|icloud|aol|ymail)\./i;
  const rang = (e) => (domaineSite && e.endsWith('@' + domaineSite) || (domaineSite && e.split('@')[1]?.endsWith('.' + domaineSite)) ? 0 : gratuit.test(e) ? 1 : 2);
  return [...emails].sort((a, b) => rang(a) - rang(b));
};

const formaterTel = (internat) => (internat ? '+' + internat : '');

// « 7,688 followers » / « 5 197 J'aime » / « 1,2 K abonnés » → nombre
const lireNombre = (s) => {
  if (!s) return null;
  let t = String(s).replace(/\s/g, '').replace(/,(?=\d{3}\b)/g, '').replace(',', '.');
  const k = /k$/i.test(t) ? 1000 : /m$/i.test(t) ? 1000000 : 1;
  const n = parseFloat(t);
  return Number.isFinite(n) ? Math.round(n * k) : null;
};

// Priorité lisible à partir du score.
const priorite = (score) => (score >= 60 ? 'Chaud' : score >= 35 ? 'Tiède' : 'Froid');

// ─────────────────────────────────────────────────────────────────────────────
// Lecture des résultats d'un moteur de recherche → { titre, lien, extrait }.
//  · « serper »    : API Serper.dev (résultats Google), 2 500 recherches offertes, sans carte.
//  · « brave-api » : API officielle Brave Search, 5 $ de crédit offerts chaque mois.
// On passe toujours par une API : la page de résultats de Brave, elle, réclame un captcha
// dès qu'elle est appelée depuis n8n (testé le 2026-10-11).
// ─────────────────────────────────────────────────────────────────────────────

const lireSerper = (json) => (json?.organic || []).map((r) => ({
  titre: nettoyer(r.title),
  lien: r.link || '',
  extrait: nettoyer([r.snippet, ...(r.attributes ? Object.values(r.attributes) : [])].join(' ')),
}));

const lireBraveApi = (json) => (json?.web?.results || []).map((r) => ({
  titre: decoderHtml(r.title),
  lien: r.url || '',
  extrait: decoderHtml([r.description, ...(r.extra_snippets || [])].join(' ')),
}));

// Lit la réponse quel que soit le moteur, et remonte une erreur claire si la clé est mauvaise.
const lireRecherche = (json) => {
  if (!json) return [];
  if (json.organic) return lireSerper(json);
  if (json.web) return lireBraveApi(json);
  const erreur = json.message || json.error?.detail || json.error?.message || (typeof json.error === 'string' ? json.error : '');
  if (erreur) throw new Error('Moteur de recherche : ' + erreur + ' (vérifie la clé dans l\'identifiant n8n).');
  return [];
};

// ─────────────────────────────────────────────────────────────────────────────
// Reconnaître une PAGE Facebook d'entreprise dans un résultat de recherche et lire
// ce que l'extrait en dit (abonnés, mentions J'aime, téléphone, WhatsApp…).
// ─────────────────────────────────────────────────────────────────────────────

// Liens qui ne sont pas des pages : publications, groupes, vidéos, photos…
const PAS_UNE_PAGE = /facebook\.com\/(?:[^/?#]+\/)?(?:posts|videos|photos|photo|reel|reels|events|groups|watch|story\.php|permalink\.php|marketplace|hashtag|share|media|notes|help|login|public|search|pg\/[^/]+\/(?:posts|photos))(?:[/?#]|$)/i;

// Renvoie { url, cle, slug } pour une page, ou null.
// (Pas de `new URL()` : il n'existe pas dans le bac à sable des nodes Code de n8n.)
const pageFacebook = (lien) => {
  const m = String(lien ?? '').match(/^https?:\/\/(?:[a-z-]+\.)?facebook\.com(\/[^?#]*)?(\?[^#]*)?/i);
  if (!m || PAS_UNE_PAGE.test(lien)) return null;
  const chemin = m[1] || '/';
  const requete = m[2] || '';
  let morceaux;
  try { morceaux = decodeURIComponent(chemin).split('/').filter(Boolean); } catch (e) { morceaux = chemin.split('/').filter(Boolean); }
  if (chemin.startsWith('/profile.php')) {
    const id = (requete.match(/[?&]id=(\d+)/) || [])[1];
    return id ? { url: `https://www.facebook.com/profile.php?id=${id}`, cle: id, slug: id } : null;
  }
  if (!morceaux.length) return null;
  // facebook.com/p/Nom-De-La-Page-1000123456/  ou  facebook.com/people/Nom/1000123456/
  if ((morceaux[0] === 'p' || morceaux[0] === 'people') && morceaux.length >= 2) {
    const id = (morceaux.join('/').match(/(\d{8,})/) || [])[1];
    const cle = id || morceaux[1].toLowerCase();
    return { url: `https://www.facebook.com/${morceaux.slice(0, morceaux[0] === 'people' ? 3 : 2).join('/')}/`, cle, slug: id || morceaux[1] };
  }
  if (morceaux.length > 1 && !/^(about|community|reviews|menu|services|shop)$/i.test(morceaux[1])) return null;
  if (/^\d+$/.test(morceaux[0]) && morceaux.length > 1) return null;
  const slug = morceaux[0];
  return { url: `https://www.facebook.com/${slug}/`, cle: slug.toLowerCase(), slug };
};

// « 7,688 followers · 799 talking about this · 262 were here » / « 5 197 J’aime · 12 abonnés »
const lireCompteurs = (texte) => {
  const t = String(texte ?? '').replace(/ | /g, ' ');
  const n = (re) => { const m = t.match(re); return m ? lireNombre(m[1]) : null; };
  return {
    abonnes: n(/([\d][\d.,\s]*[KkMm]?)\s*(?:followers|abonnés|abonné|personnes suivent)/i),
    jaime: n(/([\d][\d.,\s]*[KkMm]?)\s*(?:likes|j[’']aime|mentions j[’']aime)/i),
    enParlent: n(/([\d][\d.,\s]*[KkMm]?)\s*(?:talking about this|en parlent)/i),
  };
};

// Titre Brave/Google : « La Petite Villageoise - Restaurant | Douala | Facebook »
const nomDepuisTitre = (titre) => {
  const parties = String(titre ?? '').split(/\s+\|\s+/).map((s) => s.trim())
    .filter((s) => s && !/^facebook$/i.test(s) && !/^(meta|log in|connexion)/i.test(s));
  return (parties[0] || '').replace(/\s*[-–|]\s*(Accueil|Home|Facebook)$/i, '').trim();
};

