const RESEAUX_LIENS = {
  facebook: /https?:\/\/(?:[a-z-]+\.)?facebook\.com\/(?!sharer|share|plugins|tr\?|dialog)[A-Za-z0-9.\-_/?=]+/i,
  instagram: /https?:\/\/(?:www\.)?instagram\.com\/[A-Za-z0-9._]+/i,
  linkedin: /https?:\/\/(?:[a-z]+\.)?linkedin\.com\/(?:company|in)\/[A-Za-z0-9\-_%]+/i,
  tiktok: /https?:\/\/(?:www\.)?tiktok\.com\/@[A-Za-z0-9._]+/i,
};

const lireSite = (html, indicatif = '237') => {
  const h = String(html ?? '');
  const texte = decoderHtml(h.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' '));
  const titre = decoderHtml((h.match(/<title[^>]*>([\s\S]*?)<\/title>/i) || [])[1]);
  const description = decoderHtml((h.match(/<meta[^>]+name=["']description["'][^>]*content=["']([^"']*)/i) || [])[1]);
  const wa = [...new Set([...h.matchAll(/(?:wa\.me\/|api\.whatsapp\.com\/send\/?\?phone=|whatsapp:\/\/send\?phone=)\+?(\d{8,15})/gi)].map((m) => m[1]))];
  const telLiens = [...h.matchAll(/href=["']tel:([^"']+)/gi)].map((m) => m[1]);
  // Les liens tel: sont fiables (n'importe quel pays) ; le texte libre doit avoir le bon indicatif.
  const tels = [...new Set([...extraireTelephones(telLiens.join(' '), ''), ...extraireTelephones(texte, indicatif)])];
  const mailtos = [...h.matchAll(/mailto:([^"'?\s>]+)/gi)].map((m) => m[1]);
  const emails = extraireEmails(mailtos.join(' ') + ' ' + texte);
  const reseaux = {};
  for (const [nom, re] of Object.entries(RESEAUX_LIENS)) { const m = h.match(re); if (m) reseaux[nom] = m[0].replace(/["'<>].*$/, ''); }
  // Lien vers une page contact (on la visitera si l'accueil ne donne pas d'email).
  const contact = (h.match(/href=["']([^"'#]*(?:contact|nous-joindre|contactez|joindre|about|a-propos)[^"']*)["']/i) || [])[1] || '';
  const annees = [...texte.matchAll(/(?:©|&copy;|copyright)\s*(?:\d{4}\s*[-–]\s*)?(20\d{2}|19\d{2})/gi)].map((m) => Number(m[1]));
  return {
    titre, description, emails, tels, whatsapp: wa, reseaux, contact,
    mobile: /<meta[^>]+name=["']viewport["']/i.test(h),
    boutonWhatsApp: wa.length > 0 || /whatsapp/i.test(h),
    pixel: /fbq\(|connect\.facebook\.net\/[^"']*fbevents/i.test(h),
    analytics: /gtag\(|googletagmanager\.com|google-analytics\.com|plausible\.io|clarity\.ms/i.test(h),
    cms: /wp-content|wp-includes/i.test(h) ? 'WordPress' : /wix\.com|wixstatic/i.test(h) ? 'Wix' : /cdn\.shopify|shopify/i.test(h) ? 'Shopify' : /squarespace/i.test(h) ? 'Squarespace' : '',
    annee: annees.length ? Math.max(...annees) : null,
    taille: h.length,
  };
};

// Transforme un lien relatif de page contact en lien complet.
const lienComplet = (base, lien) => {
  if (!lien) return '';
  if (/^https?:\/\//i.test(lien)) return lien;
  const racine = (String(base).match(/^https?:\/\/[^/]+/i) || [''])[0];
  if (lien.startsWith('//')) return 'https:' + lien;
  if (lien.startsWith('/')) return racine + lien;
  return racine + '/' + lien.replace(/^\.\//, '');
};

