const BAREME = {
  nonRevendique: {
    points: 30,
    libelle: 'Profil Google non revendiqué',
    offre: 'Revendiquer et optimiser le profil Google',
    raison: () => "votre établissement n'est pas encore revendiqué sur Google Maps : vous ne pouvez ni répondre aux avis ni corriger vos informations",
  },
  pasDeSite: {
    points: 30,
    libelle: 'Pas de site web',
    offre: 'Site vitrine',
    raison: (l) => (l.siteWeb
      ? "vos clients ne trouvent qu'une page de réseau social, pas de site internet"
      : "vous n'avez pas encore de site internet"),
  },
  peuAvis: {
    points: 15,
    libelle: "Peu d'avis",
    offre: "Campagne d'avis clients",
    raison: (l, ctx) => `vous avez ${l.avis} avis sur Google, alors que la moitié de vos concurrents à ${ctx.zone} en ont plus de ${ctx.medianeAvis}`,
  },
  noteBasse: {
    points: 10,
    libelle: 'Note inférieure à 4',
    offre: 'Gestion de la réputation',
    raison: (l) => `votre note Google est de ${String(l.note).replace('.', ',')}/5`,
  },
  pasHoraires: {
    points: 5,
    libelle: 'Horaires absents',
    offre: 'Optimisation du profil Google',
    raison: () => "vos horaires d'ouverture n'apparaissent pas sur Google",
  },
};

// Médiane du nombre d'avis d'un groupe (activité + zone), pour comparer honnêtement.
const mediane = (nombres) => {
  const v = nombres.filter((n) => typeof n === 'number').sort((a, b) => a - b);
  if (!v.length) return null;
  const m = Math.floor(v.length / 2);
  return v.length % 2 ? v[m] : Math.round((v[m - 1] + v[m]) / 2);
};

// l = un lieu (voir lireReponseMaps) ; ctx = { zone, activite, medianeAvis } ; cfg = Config
const auditer = (l, ctx, cfg) => {
  const seuil = Number(cfg.seuilAvis) || 20;
  const manques = [];
  if (l.revendique === false) manques.push('nonRevendique');
  if (!estUnVraiSite(l.siteWeb)) manques.push('pasDeSite');
  if (typeof l.avis === 'number' && l.avis < seuil && ctx.medianeAvis !== null && ctx.medianeAvis > l.avis) manques.push('peuAvis');
  if (l.note !== null && l.note !== '' && l.note !== undefined && Number(l.note) < 4) manques.push('noteBasse');
  if (l.horaires === false) manques.push('pasHoraires');

  const mobile = !!l.telephoneChiffres && estMobile(l.telephoneChiffres);
  let score = manques.reduce((s, m) => s + BAREME[m].points, 0);
  if (typeof l.avis === 'number' && l.avis >= 100) score += 10; // entreprise qui tourne : elle a un budget
  if (mobile) score += 10;                                       // joignable sur WhatsApp
  if (!l.telephone) score -= 25;                                 // impossible à appeler
  score = Math.max(0, Math.min(100, score));

  const principal = manques[0];
  return {
    score,
    priorite: priorite(score),
    manques,
    pourquoi: manques.map((m) => BAREME[m].libelle).join(' · '),
