  siteMobile: { points: 15, libelle: 'Site pas adapté au téléphone', offre: 'Refonte mobile', raison: () => "votre site n'est pas adapté aux téléphones" },
  siteWhatsapp: { points: 10, libelle: 'Pas de bouton WhatsApp sur le site', offre: 'Bouton WhatsApp + assistant', raison: () => "on ne peut pas vous écrire sur WhatsApp en un clic depuis votre site" },
  siteVieux: { points: 10, libelle: 'Site pas mis à jour', offre: 'Mise à jour du site', raison: (l) => `votre site affiche encore ${l.site.annee}` },
};
