  const g = auditer({ ...l, telephone: tel, telephoneChiffres: tel }, ctx, c);
  const manques = [...g.manques];
  let score = g.score;
  if (l.site) {
    const s = l.site;
    const ajoute = (m) => { manques.push(m); score += SITE[m].points; };
    if (s.inaccessible) ajoute('siteInaccessible');
    else {
