    note: l.note ?? '',
    avis: l.avis ?? '',
    abonnes: l.abonnes ?? '',
    sources: l.sources.join(' + '),
    adresse: l.adresse,
    lienMaps: l.lienMaps,
    extrait: l.extrait,
    date: aujourdhui(),
    id: l.id,
